using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
public static class UsabilityV5Setup{public static object Run(){if(EditorApplication.isPlaying)throw new Exception("Stop authorized Play first");for(int i=0;i<UnityEngine.SceneManagement.SceneManager.sceneCount;i++)if(UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).isDirty)throw new Exception("Unsaved scene preserved; cannot switch");var setup=EditorSceneManager.GetSceneManagerSetup();string p="검증/플레이-사용성-v5/initial-editor.json";if(!File.Exists(p))File.WriteAllText(p,Newtonsoft.Json.JsonConvert.SerializeObject(new{scenes=setup,background=Application.runInBackground},Newtonsoft.Json.Formatting.Indented));EditorSceneManager.OpenScene("Assets/Scenes/DungeonTest.unity");return new{opened="DungeonTest",savedScenes=false};}}
